1251	    // 200ms was too aggressive — bun startup on slow systems (CI, Docker, Rosetta) can exceed it
1252	    let input = '';
1253	    const decoder = new TextDecoder();
1254	    const reader = Bun.stdin.stream().getReader();
1255	
1256	    const timeoutPromise = new Promise<void>((resolve) => {
1257	      setTimeout(() => resolve(), 5000);
1258	    });
1259	
1260	    const readPromise = (async () => {
1261	      while (true) {
1262	        const { done, value } = await reader.read();
1263	        if (done) break;
1264	        input += decoder.decode(value, { stream: true });
1265	      }
1266	    })();
1267	
1268	    await Promise.race([readPromise, timeoutPromise]);
1269	
1270	    if (!input || input.trim() === '') {
1271	      process.exit(0);
1272	    }
1273	
1274	    let hookInput: HookInput;
1275	    try {
1276	      hookInput = JSON.parse(input);
1277	    } catch {
1278	      process.exit(0);
1279	    }
1280	
1281	    const cwd = hookInput.cwd || process.cwd();
1282	
1283	    // Find conversation file
1284	    const conversationPath = findCurrentConversation(cwd);
1285	    if (!conversationPath) {
1286	      logExtract(`NO_CONVERSATION: ${cwd}`);
1287	      process.exit(0);
1288	    }
1289	
1290	    // One-shot legacy JSON tracker → SQLite migration (no-op after first run).
1291	    const parentDbPath = getDbPath();
1292	    migrateLegacyTrackerOnce(parentDbPath);
1293	
1294	    // Early dedup check in parent — prevents spawning duplicate children
1295	    if (wasAlreadyExtracted(conversationPath)) {
1296	      logExtract(`DEDUP_PARENT: ${conversationPath} already extracted, skipping spawn`);
1297	      process.exit(0);
1298	    }
1299	
1300	    // Counting semaphore — global cap on concurrent extractors.
1301	    // Per-conv lock is acquired by the CHILD (re-entrant defense against
1302	    // duplicate spawns); the parent only enforces global capacity here.
1303	    if (existsSync(parentDbPath)) {
1304	      const got = acquireSemaphore(
1305	        parentDbPath,
1306	        conversationPath,
1307	        process.pid,
1308	        EXTRACTION_MAX_CONCURRENT
1309	      );
1310	      if (!got) {
1311	        logExtract(
1312	          `SEMAPHORE_FULL: ${EXTRACTION_MAX_CONCURRENT} extractors already running, skipping spawn for ${conversationPath}`
1313	        );
1314	        process.exit(0);
1315	      }
1316	    }
1317	
1318	    // Spawn self in background with --extract flag.
1319	    // This way: session exits immediately AND all memory files get updated.
1320	    // Resolve bun dynamically — don't assume ~/.bun/bin (could be Homebrew, nix, etc.)
1321	    const bunPath = (() => {
1322	      const candidates = [
1323	        process.argv[0], // the bun that's running us right now
1324	        `${process.env.HOME}/.bun/bin/bun`,
1325	        '/opt/homebrew/bin/bun',
1326	        '/usr/local/bin/bun',
1327	      ];
1328	      for (const c of candidates) {
1329	        try { if (require('fs').existsSync(c)) return c; } catch {}
1330	      }
1331	      return 'bun'; // fallback to PATH lookup
1332	    })();
1333	    const child = spawn(bunPath, ['run', import.meta.path, '--extract', conversationPath, cwd], {
1334	      detached: true,
1335	      stdio: 'ignore',
1336	      env: { ...process.env, CLAUDECODE: '' },
1337	    });
1338	    child.unref();
1339	
1340	    logExtract(`SPAWNED: Self-extract PID ${child.pid} for ${conversationPath}`);
1341	    process.exit(0);
1342	  } catch (error) {
1343	    logExtract(`ERROR: ${error}`);
1344	    process.exit(0);
1345	  }
1346	}
