  1	// SQLite writers for the Stop hook (SessionExtract.ts).
  2	// Self-contained — no imports from src/. Mirrors the relevant subset of
  3	// src/lib/memory.ts so the hook can dual-write into the same tables without
  4	// pulling in the full memory module (hooks must run even if src/ is broken).
  5	//
  6	// All functions take dbPath as the first parameter for testability.
  7	// Every write is wrapped at the call site in try/catch — failures must not
  8	// block the legacy file path or cause the extraction to be marked failed.
  9	
 10	import { Database } from 'bun:sqlite';
 11	import { existsSync } from 'fs';
 12	import { join } from 'path';
 13	
 14	export function getDbPath(): string {
 15	  if (process.env.MEM_DB_PATH) return process.env.MEM_DB_PATH;
 16	  const home = process.env.HOME || process.env.USERPROFILE || '';
 17	  return join(home, '.claude', 'memory.db');
 18	}
 19	
 20	function openDb(dbPath: string): Database {
 21	  const db = new Database(dbPath);
 22	  db.exec('PRAGMA journal_mode = WAL');
 23	  return db;
 24	}
 25	
 26	function clampImportance(value: number | undefined, fallback: number): number {
 27	  const n = typeof value === 'number' && Number.isFinite(value) ? Math.round(value) : fallback;
 28	  return Math.min(10, Math.max(1, n));
 29	}
 30	
 31	function tableExists(db: Database, name: string): boolean {
 32	  const row = db
 33	    .prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name = ?")
 34	    .get(name);
 35	  return !!row;
 36	}
 37	
 38	function columnExists(db: Database, table: string, column: string): boolean {
 39	  try {
 40	    const rows = db.prepare(`PRAGMA table_info(${table})`).all() as { name: string }[];
 41	    return rows.some((r) => r.name === column);
 42	  } catch {
 43	    return false;
 44	  }
 45	}
