 61	export function writeExtractionSession(dbPath: string, entry: ExtractionSessionInput): void {
 62	  const db = openDb(dbPath);
 63	  try {
 64	    if (!tableExists(db, 'extraction_sessions')) return;
 65	    db.prepare(
 66	      `INSERT OR REPLACE INTO extraction_sessions
 67	         (session_id, project, branch, timestamp, summary, topics, conversation_path)
 68	       VALUES (?, ?, ?, ?, ?, ?, ?)`
 69	    ).run(
 70	      entry.sessionId,
 71	      entry.project,
 72	      entry.branch ?? null,
 73	      entry.timestamp,
 74	      entry.summary,
 75	      JSON.stringify(entry.topics ?? []),
 76	      entry.conversationPath
 77	    );
 78	
 79	    // Cap at 500 rows (matches legacy SESSION_INDEX.json behavior)
 80	    db.prepare(
 81	      `DELETE FROM extraction_sessions
 82	       WHERE session_id NOT IN (
 83	         SELECT session_id FROM extraction_sessions ORDER BY timestamp DESC LIMIT 500
 84	       )`
 85	    ).run();
 86	  } finally {
 87	    db.close();
 88	  }
 89	}
