 95	export interface DecisionInput {
 96	  decision: string;
 97	  confidence?: 'high' | 'medium' | 'low';
 98	  sessionId?: string | null;
 99	  project?: string | null;
100	  category?: string | null;
101	  importance?: number;
102	}
103	
104	export function writeDecisionsBatch(dbPath: string, items: DecisionInput[]): number {
105	  if (items.length === 0) return 0;
106	  const db = openDb(dbPath);
107	  try {
108	    if (!tableExists(db, 'decisions')) return 0;
109	    const hasConfidence = columnExists(db, 'decisions', 'confidence');
110	    const sql = hasConfidence
111	      ? `INSERT INTO decisions (session_id, category, project, decision, status, confidence, importance)
112	         VALUES (?, ?, ?, ?, 'active', ?, ?)`
113	      : `INSERT INTO decisions (session_id, category, project, decision, status, importance)
114	         VALUES (?, ?, ?, ?, 'active', ?)`;
115	    const stmt = db.prepare(sql);
116	    const insertMany = db.transaction((batch: DecisionInput[]) => {
117	      let n = 0;
118	      for (const it of batch) {
119	        const importance = clampImportance(it.importance, 5);
120	        if (hasConfidence) {
121	          stmt.run(
122	            it.sessionId ?? null,
123	            it.category ?? 'auto-extracted',
124	            it.project ?? null,
125	            it.decision,
126	            it.confidence ?? 'medium',
127	            importance
128	          );
129	        } else {
130	          stmt.run(
131	            it.sessionId ?? null,
132	            it.category ?? 'auto-extracted',
133	            it.project ?? null,
134	            it.decision,
135	            importance
136	          );
137	        }
138	        n++;
139	      }
140	      return n;
141	    });
142	    return insertMany(items);
143	  } finally {
144	    db.close();
145	  }
146	}
