  1	// Parse fabric-format extracted markdown into typed records the writers
  2	// can consume. Self-contained — no imports from src/ or from SessionExtract.
  3	
  4	import type {
  5	  DecisionInput,
  6	  LearningInput,
  7	  BreadcrumbInput,
  8	  ExtractionErrorInput,
  9	} from './sqlite-writers';
 10	import {
 11	  ensureDbWritable,
 12	  writeBreadcrumbsBatch,
 13	  writeDecisionsBatch,
 14	  writeExtractionErrors,
 15	  writeExtractionSession,
 16	  writeLearningsBatch,
 17	  writeLoaEntryFromExtraction,
 18	} from './sqlite-writers';
 19	
 20	export interface DualWriteContext {
 21	  sessionId: string;
 22	  sessionLabel: string;
 23	  project: string;
 24	  timestamp: string;
 25	  conversationPath: string;
 26	  topics: string[];
 27	  summary: string;
 28	  extracted: string;
 29	}
 30	
 31	export interface DualWriteResult {
 32	  sessions: number;
 33	  decisions: number;
 34	  learnings: number;
 35	  breadcrumbs: number;
 36	  errors: number;
 37	  loa: number;
 38	  failures: Record<string, string>;
 39	}
 40	
 41	function parseBulletSection(extracted: string, sectionRegex: RegExp): string[] {
 42	  const m = extracted.match(sectionRegex);
 43	  if (!m) return [];
 44	  return m[1]
 45	    .split('\n')
 46	    .filter((l) => l.trim().startsWith('-'))
 47	    .map((l) => l.replace(/^-\s*/, '').replace(/\*\*/g, '').trim())
 48	    .filter((l) => l.length > 5);
 49	}
 50	
 51	export function parseDecisionItems(
 52	  extracted: string,
 53	  ctx: Pick<DualWriteContext, 'sessionId' | 'project'>
 54	): DecisionInput[] {
 55	  const lines = parseBulletSection(
 56	    extracted,
 57	    /(?:##\s*DECISIONS\s*MADE|DECISIONS:)\s*([\s\S]*?)(?=\n##\s|$)/
 58	  );
 59	  return lines.map((line) => {
 60	    const cmatch = line.match(/\(confidence:\s*(HIGH|MEDIUM|LOW)\)/i);
 61	    const confidence = (cmatch ? cmatch[1].toLowerCase() : 'medium') as
 62	      | 'high'
 63	      | 'medium'
 64	      | 'low';
 65	    const decision = line
 66	      .replace(/\s*\(confidence:\s*(?:HIGH|MEDIUM|LOW)\)/i, '')
 67	      .replace(/\|/g, '/');
 68	    return {
 69	      decision,
 70	      confidence,
 71	      sessionId: ctx.sessionId,
 72	      project: ctx.project,
 73	      category: 'auto-extracted',
 74	    };
 75	  });
 76	}
 77	
 78	export function parseLearningItems(
 79	  extracted: string,
 80	  ctx: Pick<DualWriteContext, 'sessionId' | 'project' | 'sessionLabel'>
 81	): LearningInput[] {
 82	  // Map "## ERRORS FIXED" bullets (format `error: fix`) into learnings.
 83	  const lines = parseBulletSection(
 84	    extracted,
 85	    /(?:##\s*ERRORS?\s*FIXED|ERRORS_FIXED:)\s*([\s\S]*?)(?=\n##\s|$)/
 86	  );
 87	  const out: LearningInput[] = [];
 88	  for (const line of lines) {
 89	    const idx = line.indexOf(':');
 90	    if (idx <= 0) continue;
 91	    out.push({
 92	      problem: line.slice(0, idx).trim(),
 93	      solution: line.slice(idx + 1).trim(),
 94	      sessionId: ctx.sessionId,
 95	      project: ctx.project,
 96	      category: 'auto-extracted',
 97	      tags: ctx.sessionLabel,
 98	    });
 99	  }
100	  return out;
101	}
102	
103	export function parseBreadcrumbItems(
104	  extracted: string,
105	  ctx: Pick<DualWriteContext, 'sessionId' | 'project'>
106	): BreadcrumbInput[] {
107	  const lines = parseBulletSection(
108	    extracted,
109	    /(?:##\s*MAIN\s*IDEAS|MAIN_IDEAS:)\s*([\s\S]*?)(?=\n##\s|$)/
110	  );
111	  return lines.map((content) => ({
112	    content,
113	    category: 'extracted-idea',
114	    sessionId: ctx.sessionId,
115	    project: ctx.project,
116	  }));
117	}
118	
119	export function parseErrorPatternItems(extracted: string): ExtractionErrorInput[] {
120	  const lines = parseBulletSection(
121	    extracted,
122	    /(?:##\s*ERRORS?\s*FIXED|ERRORS_FIXED:)\s*([\s\S]*?)(?=\n##\s|$)/
123	  );
124	  const normalize = (s: string) =>
125	    s.toLowerCase().replace(/['"]/g, '').replace(/\s+/g, ' ').trim();
126	  const out: ExtractionErrorInput[] = [];
127	  for (const line of lines) {
128	    const idx = line.indexOf(':');
129	    if (idx <= 0) continue;
130	    const error = line.slice(0, idx).trim();
131	    const fix = line.slice(idx + 1).trim();
132	    out.push({ errorKey: normalize(error), error, fix });
133	  }
134	  return out;
135	}
136	
137	/**
138	 * Dual-write extracted content into SQLite. Every section is wrapped in its
139	 * own try/catch — a failure on one writer must not block the others, and the
140	 * whole function must not throw.
141	 */
142	export function dualWriteToSqlite(
143	  dbPath: string,
144	  ctx: DualWriteContext
145	): DualWriteResult {
146	  const result: DualWriteResult = {
147	    sessions: 0,
148	    decisions: 0,
149	    learnings: 0,
150	    breadcrumbs: 0,
151	    errors: 0,
152	    loa: 0,
153	    failures: {},
154	  };
155	
156	  if (!ensureDbWritable(dbPath)) {
157	    result.failures._db = 'not writable';
158	    return result;
159	  }
160	
161	  try {
162	    writeExtractionSession(dbPath, {
163	      sessionId: ctx.sessionId,
164	      project: ctx.project,
165	      timestamp: ctx.timestamp,
166	      summary: ctx.summary,
167	      topics: ctx.topics,
168	      conversationPath: ctx.conversationPath,
169	    });
170	    result.sessions = 1;
171	  } catch (e: any) {
172	    result.failures.sessions = e?.message || String(e);
173	  }
174	
175	  try {
176	    result.decisions = writeDecisionsBatch(dbPath, parseDecisionItems(ctx.extracted, ctx));
177	  } catch (e: any) {
178	    result.failures.decisions = e?.message || String(e);
179	  }
180	
181	  try {
182	    result.learnings = writeLearningsBatch(dbPath, parseLearningItems(ctx.extracted, ctx));
183	  } catch (e: any) {
184	    result.failures.learnings = e?.message || String(e);
185	  }
186	
187	  try {
188	    result.breadcrumbs = writeBreadcrumbsBatch(
189	      dbPath,
190	      parseBreadcrumbItems(ctx.extracted, ctx)
191	    );
192	  } catch (e: any) {
193	    result.failures.breadcrumbs = e?.message || String(e);
194	  }
195	
196	  try {
197	    result.errors = writeExtractionErrors(dbPath, parseErrorPatternItems(ctx.extracted));
198	  } catch (e: any) {
199	    result.failures.errors = e?.message || String(e);
200	  }
201	
202	  try {
203	    const loaId = writeLoaEntryFromExtraction(dbPath, {
204	      title: `${ctx.sessionLabel} — ${ctx.timestamp}`,
205	      description: ctx.summary,
206	      fabricExtract: ctx.extracted,
207	      sessionId: ctx.sessionId,
208	      project: ctx.project,
209	      tags: ctx.topics.join(','),
210	    });
211	    result.loa = loaId ? 1 : 0;
212	  } catch (e: any) {
213	    result.failures.loa = e?.message || String(e);
214	  }
215	
216	  return result;
217	}

  1	// Extraction per-conversation lock — self-contained, no imports from src/
  2	// Distinct from the semaphore (global capacity cap):
  3	//   Semaphore = "are we under the max concurrent limit?" (global)
  4	//   Lock       = "is THIS specific conversation already being extracted?" (per-conv mutex)
  5	//
  6	// All functions take dbPath as first parameter for testability.
  7	
  8	import { Database } from 'bun:sqlite';
  9	import { isPidAlive } from './pid-utils';
 10	
 11	const DEFAULT_TTL_SECONDS = 600; // 10 minutes
 12	
 13	function openDb(dbPath: string): Database {
 14	  const db = new Database(dbPath);
 15	  db.exec('PRAGMA journal_mode = WAL');
 16	  return db;
 17	}
 18	
 19	/**
 20	 * Attempt to acquire a per-conversation extraction lock.
 21	 *
 22	 * Algorithm:
 23	 *   1. Delete any expired row for this path (time-based TTL)
 24	 *   2. INSERT OR IGNORE — atomic, only succeeds if no row exists
 25	 *   3. Return whether we got the lock (changes > 0)
 26	 *
 27	 * @param dbPath      Path to SQLite database
 28	 * @param convPath    Conversation file path (PK for the lock)
 29	 * @param pid         PID of the acquiring process
 30	 * @param ttlSeconds  Expiry threshold for stale lock cleanup (default 600)
 31	 * @returns true if lock acquired, false if already held
 32	 */
 33	export function childAcquireLock(
 34	  dbPath: string,
 35	  convPath: string,
 36	  pid: number,
 37	  ttlSeconds?: number
 38	): boolean {
 39	  const ttl = ttlSeconds ?? DEFAULT_TTL_SECONDS;
 40	  const db = openDb(dbPath);
 41	  try {
 42	    // Remove expired lock for this specific path so it doesn't block us
 43	    const cutoffSeconds = `-${ttl} seconds`;
 44	    db.prepare(
 45	      "DELETE FROM extraction_locks WHERE conversation_path = ? AND started_at < datetime('now', ?)"
 46	    ).run(convPath, cutoffSeconds);
 47	
 48	    // Atomic insert — OR IGNORE means we don't overwrite an active lock
 49	    const result = db
 50	      .prepare(
 51	        "INSERT OR IGNORE INTO extraction_locks (conversation_path, pid, started_at) VALUES (?, ?, datetime('now'))"
 52	      )
 53	      .run(convPath, pid);
 54	
 55	    return result.changes > 0;
 56	  } finally {
 57	    db.close();
 58	  }
 59	}
 60	
 61	/**
 62	 * Release the per-conversation lock.
 63	 * Only removes the row if the PID matches — protects against releasing
 64	 * a lock owned by a different process.
 65	 *
 66	 * @param dbPath   Path to SQLite database
 67	 * @param convPath Conversation file path
 68	 * @param pid      PID of the releasing process (must match stored PID)
 69	 */
 70	export function childReleaseLock(dbPath: string, convPath: string, pid: number): void {
 71	  const db = openDb(dbPath);
 72	  try {
 73	    db.prepare(
 74	      'DELETE FROM extraction_locks WHERE conversation_path = ? AND pid = ?'
 75	    ).run(convPath, pid);
 76	  } finally {
 77	    db.close();
 78	  }
 79	}
 80	
 81	/**
 82	 * Check whether an active lock is held for a conversation path.
 83	 * Used by the parent (SessionExtract) before deciding to spawn a child.
 84	 *
 85	 * A lock is considered held if:
 86	 *   - A row exists for the path, AND
 87	 *   - The row is not expired (within TTL), AND
 88	 *   - The owning PID is still alive
 89	 *
 90	 * @param dbPath      Path to SQLite database
 91	 * @param convPath    Conversation file path
 92	 * @param ttlSeconds  Maximum lock age before considered expired (default 600)
 93	 * @returns true if lock is actively held, false otherwise
 94	 */
 95	export function parentIsLockHeld(
 96	  dbPath: string,
 97	  convPath: string,
 98	  ttlSeconds?: number
 99	): boolean {
100	  const ttl = ttlSeconds ?? DEFAULT_TTL_SECONDS;
101	  const db = openDb(dbPath);
102	  try {
103	    const row = db
104	      .prepare('SELECT pid, started_at FROM extraction_locks WHERE conversation_path = ?')
105	      .get(convPath) as { pid: number; started_at: string } | undefined;
106	
107	    if (!row) return false;
108	
109	    // Time-based expiry check
110	    const startedAt = new Date(row.started_at + 'Z'); // SQLite datetime is UTC, ensure parsed as UTC
111	    const ageSeconds = (Date.now() - startedAt.getTime()) / 1000;
112	    if (ageSeconds > ttl) return false;
113	
114	    // PID liveness check
115	    return isPidAlive(row.pid);
116	  } finally {
117	    db.close();
118	  }
119	}

  1	// Extraction counting semaphore — self-contained, no imports from src/
  2	// All functions take dbPath as first parameter for testability.
  3	
  4	import { Database } from 'bun:sqlite';
  5	import { isPidAlive } from './pid-utils';
  6	
  7	const DEFAULT_MAX_CONCURRENT = 3;
  8	const DEFAULT_TTL_SECONDS = 600; // 10 minutes
  9	
 10	function openDb(dbPath: string): Database {
 11	  const db = new Database(dbPath);
 12	  db.exec('PRAGMA journal_mode = WAL');
 13	  return db;
 14	}
 15	
 16	/**
 17	 * Sweep expired locks from extraction_locks.
 18	 * Two strategies combined:
 19	 *   1. Time-based: remove rows where started_at older than TTL seconds
 20	 *   2. PID liveness: remove rows where the owning PID is dead
 21	 *
 22	 * @param dbPath      Path to SQLite database
 23	 * @param ttlSeconds  Lock TTL in seconds (default 600)
 24	 * @returns Number of locks removed
 25	 */
 26	export function sweepExpiredLocks(dbPath: string, ttlSeconds?: number): number {
 27	  const ttl =
 28	    ttlSeconds ??
 29	    parseInt(process.env.EXTRACTION_LOCK_TTL_SECONDS || String(DEFAULT_TTL_SECONDS), 10);
 30	
 31	  const db = openDb(dbPath);
 32	  try {
 33	    // Strategy 1: time-based TTL sweep using bound parameter
 34	    const cutoffSeconds = `-${ttl} seconds`;
 35	    const timeResult = db
 36	      .prepare("DELETE FROM extraction_locks WHERE started_at < datetime('now', ?)")
 37	      .run(cutoffSeconds);
 38	    let removed = timeResult.changes;
 39	
 40	    // Strategy 2: PID liveness sweep — check all remaining locks
 41	    interface LockRow {
 42	      conversation_path: string;
 43	      pid: number;
 44	    }
 45	    const remaining = db
 46	      .prepare('SELECT conversation_path, pid FROM extraction_locks')
 47	      .all() as LockRow[];
 48	
 49	    for (const row of remaining) {
 50	      if (!isPidAlive(row.pid)) {
 51	        const pidResult = db
 52	          .prepare('DELETE FROM extraction_locks WHERE conversation_path = ? AND pid = ?')
 53	          .run(row.conversation_path, row.pid);
 54	        removed += pidResult.changes;
 55	      }
 56	    }
 57	
 58	    return removed;
 59	  } finally {
 60	    db.close();
 61	  }
 62	}
 63	
 64	/**
 65	 * Get the current count of active locks.
 66	 */
 67	export function getActiveLockCount(dbPath: string): number {
 68	  const db = openDb(dbPath);
 69	  try {
 70	    const row = db
 71	      .prepare('SELECT COUNT(*) as cnt FROM extraction_locks')
 72	      .get() as { cnt: number };
 73	    return row.cnt;
 74	  } finally {
 75	    db.close();
 76	  }
 77	}
 78	
 79	/**
 80	 * Try to acquire a semaphore slot for the given conversation path.
 81	 *
 82	 * Algorithm:
 83	 *   1. Sweep expired locks (time-based + PID liveness)
 84	 *   2. Count active locks
 85	 *   3. If >= maxConcurrent, return false
 86	 *   4. INSERT OR IGNORE — if changes > 0, we got the slot
 87	 *   5. Return whether acquired
 88	 *
 89	 * @param dbPath         Path to SQLite database
 90	 * @param convPath       Conversation path (PK for the lock)
 91	 * @param pid            PID of the acquiring process
 92	 * @param maxConcurrent  Maximum concurrent slots (default 3)
 93	 * @param ttlSeconds     Lock TTL for sweep (default 600)
 94	 * @returns true if acquired, false if rejected
 95	 */
 96	export function acquireSemaphore(
 97	  dbPath: string,
 98	  convPath: string,
 99	  pid: number,
100	  maxConcurrent: number = DEFAULT_MAX_CONCURRENT,
101	  ttlSeconds?: number
102	): boolean {
103	  const ttl =
104	    ttlSeconds ??
105	    parseInt(process.env.EXTRACTION_LOCK_TTL_SECONDS || String(DEFAULT_TTL_SECONDS), 10);
106	
107	  const db = openDb(dbPath);
108	  try {
109	    // Single transaction: sweep + count + insert to prevent TOCTOU
110	    db.exec('BEGIN IMMEDIATE');
111	    try {
112	      // Sweep expired locks (time-based)
113	      const cutoffSeconds = `-${ttl} seconds`;
114	      db.prepare("DELETE FROM extraction_locks WHERE started_at < datetime('now', ?)").run(cutoffSeconds);
115	
116	      // PID liveness sweep on remaining locks
117	      interface LockRow { conversation_path: string; pid: number; }
118	      const remaining = db.prepare('SELECT conversation_path, pid FROM extraction_locks').all() as LockRow[];
119	      const deadPaths = remaining.filter(r => !isPidAlive(r.pid)).map(r => r.conversation_path);
120	      for (const path of deadPaths) {
121	        db.prepare('DELETE FROM extraction_locks WHERE conversation_path = ?').run(path);
122	      }
123	
124	      // Check capacity
125	      const activeCount = (db.prepare('SELECT COUNT(*) as cnt FROM extraction_locks').get() as { cnt: number }).cnt;
126	      if (activeCount >= maxConcurrent) {
127	        db.exec('COMMIT');
128	        return false;
129	      }
130	
131	      // Atomic insert
132	      const result = db.prepare(
133	        "INSERT OR IGNORE INTO extraction_locks (conversation_path, pid, started_at) VALUES (?, ?, datetime('now'))"
134	      ).run(convPath, pid);
135	
136	      db.exec('COMMIT');
137	      return result.changes > 0;
138	    } catch (e) {
139	      db.exec('ROLLBACK');
140	      throw e;
141	    }
142	  } finally {
143	    db.close();
144	  }
145	}
146	
147	/**
148	 * Release the semaphore lock for the given conversation path.
149	 * Safe to call even if the lock doesn't exist.
150	 */
151	export function releaseSemaphore(dbPath: string, convPath: string): void {
152	  const db = openDb(dbPath);
153	  try {
154	    db.prepare('DELETE FROM extraction_locks WHERE conversation_path = ?').run(convPath);
155	  } finally {
156	    db.close();
157	  }
158	}

 1	// Extraction tracker CRUD — self-contained, no imports from src/
