14	  size: number;
15	  extracted_at: string | null;
16	  failed_at: string | null;
17	  retry_after: string | null;
18	  error: string | null;
19	  skipped: number;
20	}
21	
22	export function getExtractionRecord(dbPath: string, conversationPath: string): ExtractionRecord | null {
23	  const db = openDb(dbPath);
24	  try {
25	    const row = db
26	      .prepare('SELECT * FROM extraction_tracker WHERE conversation_path = ?')
27	      .get(conversationPath) as ExtractionRecord | undefined;
28	    return row ?? null;
29	  } finally {
30	    db.close();
31	  }
32	}
33	
34	export function markAsExtracted(dbPath: string, conversationPath: string, size: number): void {
35	  const db = openDb(dbPath);
36	  try {
37	    db.prepare(
38	      "INSERT OR REPLACE INTO extraction_tracker (conversation_path, size, extracted_at) VALUES (?, ?, datetime('now'))"
39	    ).run(conversationPath, size);
40	  } finally {
41	    db.close();
42	  }
43	}
44	
45	export function markAsFailed(
46	  dbPath: string,
47	  conversationPath: string,
48	  size: number,
49	  error?: string
50	): void {
51	  const db = openDb(dbPath);
52	  try {
53	    db.prepare(
54	      "INSERT OR REPLACE INTO extraction_tracker (conversation_path, size, failed_at, retry_after, error) VALUES (?, ?, datetime('now'), datetime('now', '+24 hours'), ?)"
55	    ).run(conversationPath, size, error ?? null);
56	  } finally {
57	    db.close();
58	  }
59	}
60	
61	export function wasAlreadyExtracted(
62	  dbPath: string,
63	  conversationPath: string,
64	  currentSize: number
65	): boolean {
66	  const record = getExtractionRecord(dbPath, conversationPath);
67	  if (!record) return false;
68	
69	  // Successfully extracted and size hasn't grown more than 50%
70	  if (record.extracted_at) {
71	    const growth = (currentSize - record.size) / record.size;
72	    return growth <= 0.5;
73	  }
74	
75	  // Failed but still within retry cooldown
76	  if (record.failed_at && record.retry_after) {
77	    const retryAfter = new Date(record.retry_after);
78	    return retryAfter > new Date();
79	  }
80	
81	  return false;
82	}
83	
84	export function getAllTrackerRecords(dbPath: string): ExtractionRecord[] {
85	  const db = openDb(dbPath);
86	  try {
87	    return db.prepare('SELECT * FROM extraction_tracker').all() as ExtractionRecord[];
88	  } finally {
89	    db.close();
90	  }
91	}

