  1	// JSON-to-SQLite migration for extraction state files.
  2	// Self-contained — no imports from src/.
  3	
  4	import { Database } from 'bun:sqlite';
  5	import { readFileSync } from 'fs';
  6	
  7	function openDb(dbPath: string): Database {
  8	  const db = new Database(dbPath);
  9	  db.exec('PRAGMA journal_mode = WAL');
 10	  return db;
 11	}
 12	
 13	// ---------------------------------------------------------------------------
 14	// Tracker JSON types
 15	// ---------------------------------------------------------------------------
 16	
 17	interface TrackerEntry {
 18	  size?: number;
 19	  extractedAt?: string;
 20	  failedAt?: string;
 21	  retryAfter?: string;
 22	  error?: string;
 23	  skipped?: number;
 24	}
 25	
 26	type TrackerJson = Record<string, TrackerEntry>;
 27	
 28	// ---------------------------------------------------------------------------
 29	// Session Index JSON types
 30	// ---------------------------------------------------------------------------
 31	
 32	interface SessionIndexEntry {
 33	  sessionId: string;
 34	  project?: string;
 35	  branch?: string;
 36	  timestamp: string;
 37	  summary?: string;
 38	  topics?: string[];
 39	  conversationPath?: string;
 40	}
 41	
 42	// ---------------------------------------------------------------------------
 43	// Error Patterns JSON types
 44	// ---------------------------------------------------------------------------
 45	
 46	interface ErrorPatternEntry {
 47	  error: string;
 48	  fix?: string;
 49	  context?: string;
 50	  cause?: string;
 51	  file?: string;
 52	  date?: string;
 53	  firstSeen?: string;
 54	  lastSeen?: string;
 55	}
 56	
 57	interface ErrorPatternsJson {
 58	  patterns: ErrorPatternEntry[];
 59	}
 60	
 61	// ---------------------------------------------------------------------------
 62	// migrateTrackerJson
 63	// ---------------------------------------------------------------------------
 64	
 65	export function migrateTrackerJson(
 66	  jsonPath: string,
 67	  dbPath: string
 68	): { imported: number } {
 69	  const raw = readFileSync(jsonPath, 'utf-8');
 70	  const data: TrackerJson = JSON.parse(raw); // throws on invalid JSON
 71	
 72	  const db = openDb(dbPath);
 73	  try {
 74	    const stmt = db.prepare(`
 75	      INSERT OR REPLACE INTO extraction_tracker
 76	        (conversation_path, size, extracted_at, failed_at, retry_after, error, skipped)
 77	      VALUES (?, ?, ?, ?, ?, ?, ?)
 78	    `);
 79	
 80	    let imported = 0;
 81	    for (const [conversationPath, entry] of Object.entries(data)) {
 82	      stmt.run(
 83	        conversationPath,
 84	        entry.size ?? 0,
 85	        entry.extractedAt ?? null,
 86	        entry.failedAt ?? null,
 87	        entry.retryAfter ?? null,
 88	        entry.error ?? null,
 89	        entry.skipped ?? 0
 90	      );
 91	      imported++;
 92	    }
 93	
 94	    return { imported };
 95	  } finally {
 96	    db.close();
 97	  }
 98	}
 99	
100	// ---------------------------------------------------------------------------
101	// migrateSessionIndex
102	// ---------------------------------------------------------------------------
103	
104	export function migrateSessionIndex(
105	  jsonPath: string,
106	  dbPath: string
107	): { imported: number } {
108	  const raw = readFileSync(jsonPath, 'utf-8');
109	  const data: SessionIndexEntry[] = JSON.parse(raw);
110	
111	  const db = openDb(dbPath);
112	  try {
113	    const stmt = db.prepare(`
114	      INSERT OR REPLACE INTO extraction_sessions
115	        (session_id, project, branch, timestamp, summary, topics, conversation_path)
116	      VALUES (?, ?, ?, ?, ?, ?, ?)
117	    `);
118	
119	    let imported = 0;
120	    for (const entry of data) {
121	      if (!entry.timestamp) continue; // timestamp is required
122	
123	      stmt.run(
124	        entry.sessionId,
125	        entry.project ?? null,
126	        entry.branch ?? null,
127	        entry.timestamp,
128	        entry.summary ?? null,
129	        JSON.stringify(entry.topics ?? []),
130	        entry.conversationPath ?? null
131	      );
132	      imported++;
133	    }
134	
135	    // Cap at 500 rows (matches legacy SESSION_INDEX.json behavior)
136	    db.prepare(`
137	      DELETE FROM extraction_sessions
138	      WHERE session_id NOT IN (
139	        SELECT session_id FROM extraction_sessions ORDER BY timestamp DESC LIMIT 500
140	      )
141	    `).run();
142	
143	    return { imported };
144	  } finally {
145	    db.close();
146	  }
147	}
148	
149	// ---------------------------------------------------------------------------
150	// migrateErrorPatterns
151	// ---------------------------------------------------------------------------
152	
153	export function migrateErrorPatterns(
154	  jsonPath: string,
155	  dbPath: string
156	): { imported: number } {
157	  const raw = readFileSync(jsonPath, 'utf-8');
158	  const data: ErrorPatternsJson = JSON.parse(raw);
159	  const patterns = data.patterns ?? [];
160	
161	  const db = openDb(dbPath);
162	  try {
163	    const stmt = db.prepare(`
164	      INSERT OR REPLACE INTO extraction_errors
165	        (error_key, error, fix, context, first_seen, last_seen)
166	      VALUES (?, ?, ?, ?, ?, ?)
167	    `);
168	
169	    let imported = 0;
170	    for (const pattern of patterns) {
171	      // Real data uses 'date' and 'cause'; fixtures use 'firstSeen'/'lastSeen'/'context'
172	      const firstSeen = pattern.firstSeen ?? pattern.date ?? new Date().toISOString();
173	      const lastSeen = pattern.lastSeen ?? pattern.date ?? new Date().toISOString();
174	      const context = pattern.context ?? pattern.cause ?? null;
175	      stmt.run(
176	        pattern.error,
177	        pattern.error,
178	        pattern.fix ?? null,
179	        context,
180	        firstSeen,
181	        lastSeen
182	      );
183	      imported++;
184	    }
185	
186	    return { imported };
187	  } finally {
188	    db.close();
189	  }
190	}
191	
192	// ---------------------------------------------------------------------------
193	// migrateAll
194	// ---------------------------------------------------------------------------
195	
196	export interface MigrateAllOptions {
197	  trackerPath?: string;
198	  sessionIndexPath?: string;
199	  errorPatternsPath?: string;
200	}
201	
202	export function migrateAll(
203	  dbPath: string,
204	  options: MigrateAllOptions
205	): { tracker: number; sessions: number; errors: number } {
206	  // Each sub-function opens its own connection and uses INSERT OR REPLACE,
207	  // making the migration idempotent. Re-running after partial failure is safe.
208	  let tracker = 0;
209	  let sessions = 0;
210	  let errors = 0;
211	
212	  if (options.trackerPath) {
213	    tracker = migrateTrackerJson(options.trackerPath, dbPath).imported;
214	  }
215	
216	  if (options.sessionIndexPath) {
217	    sessions = migrateSessionIndex(options.sessionIndexPath, dbPath).imported;
218	  }
219	
220	  if (options.errorPatternsPath) {
221	    errors = migrateErrorPatterns(options.errorPatternsPath, dbPath).imported;
222	  }
223	
224	  return { tracker, sessions, errors };
225	}

