141	/**
142	 * Extract actual text from content blocks (handles arrays and nested structures)
143	 */
144	function extractTextFromContent(content: any): string {
145	  if (typeof content === 'string') {
146	    return content;
147	  }
148	
149	  if (Array.isArray(content)) {
150	    const textParts: string[] = [];
151	    for (const block of content) {
152	      // Extract text blocks
153	      if (block.type === 'text' && block.text) {
154	        textParts.push(block.text);
155	      }
156	      // Skip thinking blocks, tool_use, tool_result - noise for memory
157	    }
158	    return textParts.join('\n');
159	  }
160	
161	  // Object with text property
162	  if (content?.text) {
163	    return content.text;
164	  }
165	
166	  return '';
167	}
