169	/**
170	 * Extract message content from JSONL conversation
171	 * Filters noise: tool results, thinking blocks, system messages
172	 */
173	function extractMessages(jsonlPath: string): string {
174	  const content = readFileSync(jsonlPath, 'utf-8');
175	  const lines = content.trim().split('\n');
176	
177	  const messages: string[] = [];
178	  for (const line of lines) {
179	    try {
180	      const entry = JSON.parse(line);
181	
182	      // Skip non-message entries (summaries, file-history, etc.)
183	      if (!entry.message?.content) continue;
184	
185	      const role = entry.message.role;
186	
187	      // Only include user and assistant messages
188	      if (role !== 'user' && role !== 'assistant') continue;
189	
190	      // Extract actual text (handles arrays properly)
191	      const text = extractTextFromContent(entry.message.content);
192	
193	      // Skip empty or tool-only messages
194	      if (!text || text.trim().length < 10) continue;
195	
196	      // Skip messages that look like tool results (often start with [ or {)
197	      if (text.trim().startsWith('[{') || text.trim().startsWith('{"tool_use_id"')) continue;
198	
199	      // Truncate very long messages but keep more context
200	      const truncated = text.length > 4000 ? text.slice(0, 4000) + '...[truncated]' : text;
201	      messages.push(`[${role.toUpperCase()}]: ${truncated}`);
202	
203	    } catch {
204	      // Skip malformed lines
205	    }
206	  }
207	
208	  return messages.join('\n\n');
209	}
