211	/**
212	 * Per-conversation dedup tracking — backed by SQLite `extraction_tracker` table
213	 * (replaces the legacy `.extraction_tracker.json` file).
214	 *
215	 * Re-extract policy (preserved from the JSON-era code):
216	 *   - Never extracted   → true (needs extraction)
217	 *   - Extracted, grew ≤50% → false (skip)
218	 *   - Extracted, grew >50% → true (re-extract)
219	 *   - Failed within 24h → false (cooldown)
220	 *   - Failed >24h ago   → true (retry)
221	 */
222	function wasAlreadyExtracted(convPath: string): boolean {
223	  const dbPath = getDbPath();
224	  if (!existsSync(dbPath)) {
225	    // DB hasn't been initialized (`mem init` not run). Without the tracker
226	    // table we can't dedup — return false so the caller proceeds. The lock
227	    // primitive still prevents duplicate concurrent extractions.
228	    return false;
229	  }
230	  try {
231	    const currentSize = statSync(convPath).size;
232	    return trackerWasAlreadyExtracted(dbPath, convPath, currentSize);
233	  } catch {
234	    return false;
235	  }
236	}
