240	 * Releases any held per-conversation lock + semaphore slot.
241	 */
242	function markAsExtracted(convPath: string): void {
243	  const dbPath = getDbPath();
244	  try {
245	    if (existsSync(dbPath)) {
246	      const size = statSync(convPath).size;
247	      trackerMarkAsExtracted(dbPath, convPath, size);
248	    }
249	  } catch {}
250	  releaseChildLockSafe(convPath);
251	}
