253	/**
254	 * Mark conversation as failed extraction with 24-hour retry window.
255	 * Releases any held per-conversation lock + semaphore slot.
256	 */
257	function markAsFailed(convPath: string, error?: string): void {
258	  const dbPath = getDbPath();
259	  try {
260	    if (existsSync(dbPath)) {
261	      let size = 0;
262	      try { size = statSync(convPath).size; } catch {}
263	      trackerMarkAsFailed(dbPath, convPath, size, error);
264	    }
265	  } catch {}
266	  releaseChildLockSafe(convPath);
267	}
