269	/**
270	 * Release the per-conversation lock + semaphore slot.
271	 *
272	 * The semaphore row (extraction_locks PK on conversation_path) doubles as
273	 * the per-conv lock, so releasing the semaphore is sufficient regardless of
274	 * whether the parent or the child inserted the row. We also call the
275	 * pid-checked childReleaseLock as a defense — no-op if PIDs don't match,
276	 * useful when --reextract* acquired the row under the current PID.
277	 */
278	function releaseChildLockSafe(convPath: string): void {
279	  try {
280	    const dbPath = getDbPath();
281	    if (!existsSync(dbPath)) return;
282	    childReleaseLock(dbPath, convPath, process.pid);
283	    releaseSemaphore(dbPath, convPath);
284	  } catch {}
285	}
