323	/**
324	 * Extract topics from fabric output
325	 * Matches both "## HEADING" markdown format and "HEADING:" legacy format
326	 */
327	function extractTopics(fabricOutput: string): string[] {
328	  const topics: string[] = [];
329	
330	  // Extract from DECISIONS MADE, MAIN IDEAS, and INSIGHTS sections
331	  const patterns = [
332	    /(?:##\s*DECISIONS\s*MADE|DECISIONS:)\s*([\s\S]*?)(?=\n##\s|$)/,
333	    /(?:##\s*MAIN\s*IDEAS|MAIN_IDEAS:)\s*([\s\S]*?)(?=\n##\s|$)/,
334	    /(?:##\s*INSIGHTS|INSIGHTS:)\s*([\s\S]*?)(?=\n##\s|$)/
335	  ];
336	
337	  for (const pattern of patterns) {
338	    const match = fabricOutput.match(pattern);
339	    if (match) {
340	      const lines = match[1].split('\n').filter(l => l.trim().startsWith('-'));

340	      const lines = match[1].split('\n').filter(l => l.trim().startsWith('-'));
341	      for (const line of lines.slice(0, 3)) { // Max 3 per section
342	        // Strip markdown bold markers and leading bullet
343	        const topic = line.replace(/^-\s*/, '').replace(/\*\*/g, '').split(':')[0].trim();
344	        if (topic && topic.length < 50) {
345	          topics.push(topic);
