418	/**
419	 * Extract and append decisions from fabric output to DECISIONS.log
420	 * Matches both "## DECISIONS MADE" (fabric) and "DECISIONS:" (legacy) formats
421	 * Deduplicates against existing decisions using normalized text comparison
422	 */
423	function appendDecisions(fabricOutput: string, sessionLabel: string, timestamp: string): void {
424	  const decisionsMatch = fabricOutput.match(/(?:##\s*DECISIONS\s*MADE|DECISIONS:)\s*([\s\S]*?)(?=\n##\s|$)/);
425	  if (!decisionsMatch) return;
426	
427	  const lines = decisionsMatch[1]
428	    .split('\n')
429	    .filter(l => l.trim().startsWith('-'))
430	    .map(l => l.replace(/^-\s*/, '').replace(/\*\*/g, '').trim())
431	    .filter(l => l.length > 5);
432	
433	  if (lines.length === 0) return;
434	
435	  // Load existing decisions for deduplication
436	  const normalize = (s: string) => s.toLowerCase().replace(/['"]/g, '').replace(/\s+/g, ' ').trim();
437	  const existingDecisions = new Set<string>();
438	
439	  if (existsSync(DECISIONS_PATH)) {
440	    const content = readFileSync(DECISIONS_PATH, 'utf-8');
441	    for (const line of content.split('\n')) {
442	      if (line.startsWith('#') || line.trim() === '') continue;
443	      const parts = line.split('|');
444	      if (parts.length >= 4) {
445	        // New format: timestamp|session|confidence|decision
446	        const decision = parts.slice(3).join('|');
447	        existingDecisions.add(normalize(decision));
448	      } else if (parts.length >= 3) {
449	        // Legacy format: timestamp|session|decision
450	        const decision = parts.slice(2).join('|');
451	        existingDecisions.add(normalize(decision));
452	      }
453	    }
454	  }
455	
456	  // Filter out duplicates
457	  const newEntries: string[] = [];
458	  let skipped = 0;
459	
460	  for (const line of lines) {
461	    const normalized = normalize(line);
462	    if (existingDecisions.has(normalized)) {
463	      skipped++;
464	      continue;
465	    }
466	    existingDecisions.add(normalized);
467	    // Parse confidence suffix: (confidence: HIGH|MEDIUM|LOW)
468	    const confidenceMatch = line.match(/\(confidence:\s*(HIGH|MEDIUM|LOW)\)/i);
469	    const confidence = confidenceMatch ? confidenceMatch[1].toLowerCase() : 'medium';
470	    const cleanLine = line.replace(/\s*\(confidence:\s*(?:HIGH|MEDIUM|LOW)\)/i, '').replace(/\|/g, '/');
471	    newEntries.push(`${timestamp}|${sessionLabel}|${confidence}|${cleanLine}`);
472	  }
473	
474	  if (newEntries.length > 0) {
475	    appendFileSync(DECISIONS_PATH, newEntries.join('\n') + '\n', 'utf-8');
476	    console.error(`[FabricExtract] Appended ${newEntries.length} decisions to DECISIONS.log${skipped > 0 ? ` (${skipped} skipped as duplicates)` : ''}`);
477	  } else if (skipped > 0) {
478	    console.error(`[FabricExtract] Skipped ${skipped} duplicate decisions`);
479	  }
480	}
