503	/**
504	 * Extract and append errors from fabric output to ERROR_PATTERNS.json
505	 * Matches both "## ERRORS FIXED" and "ERRORS_FIXED:" formats
506	 */
507	function appendErrors(fabricOutput: string, sessionLabel: string, timestamp: string): void {
508	  const errorsMatch = fabricOutput.match(/(?:##\s*ERRORS?\s*FIXED|ERRORS_FIXED:)\s*([\s\S]*?)(?=\n##\s|$)/);
509	  if (!errorsMatch) return;
510	
511	  const lines = errorsMatch[1]
512	    .split('\n')
513	    .filter(l => l.trim().startsWith('-'))
514	    .map(l => l.replace(/^-\s*/, '').replace(/\*\*/g, '').trim())
515	    .filter(l => l.includes(':'));
516	
517	  if (lines.length === 0) return;
518	
519	  // Load existing patterns
520	  let data: { patterns: any[]; meta: any } = { patterns: [], meta: {} };
521	  if (existsSync(ERRORS_PATH)) {
522	    try {
523	      data = JSON.parse(readFileSync(ERRORS_PATH, 'utf-8'));
524	    } catch {
525	      data = { patterns: [], meta: {} };
526	    }
527	  }
528	
529	  // Build set of existing error keys for dedup (normalized: lowercase, no quotes, trimmed)
530	  const normalize = (s: string) => s.toLowerCase().replace(/['"]/g, '').replace(/\s+/g, ' ').trim();
531	  const existingKeys = new Set(data.patterns.map((p: any) => normalize(p.error || '')));
532	
533	  // Add new patterns (skip duplicates)
534	  let added = 0;
535	  for (const line of lines) {
536	    const colonIdx = line.indexOf(':');
537	    if (colonIdx > 0) {
538	      const error = line.slice(0, colonIdx).trim();
539	      const fix = line.slice(colonIdx + 1).trim();
540	      const key = normalize(error);
541	      if (existingKeys.has(key)) continue;
542	      existingKeys.add(key);
543	      data.patterns.push({
544	        error,
545	        cause: 'auto-extracted',
546	        fix,
547	        file: sessionLabel,
548	        date: timestamp
549	      });
550	      added++;
551	    }
552	  }
553	
554	  if (added === 0) {
555	    console.error(`[FabricExtract] No new error patterns (all ${lines.length} already exist)`);
556	    return;
557	  }
558	
559	  data.meta = { purpose: 'Pattern match errors for instant recall', updated: timestamp };
560	  writeFileSync(ERRORS_PATH, JSON.stringify(data, null, 2), 'utf-8');
561	  console.error(`[FabricExtract] Appended ${added} new error patterns (${lines.length - added} skipped as duplicates)`);
562	}
