188	export interface MigrationResult {
189	  from: number;
190	  to: number;
191	  applied: number;
192	}
193	
194	/**
195	 * Apply pending migrations to the database.
196	 *
197	 * Reads PRAGMA user_version to determine current state, then applies
198	 * each migration in order within its own transaction. On failure,
199	 * the failing migration is rolled back and an error is thrown.
200	 */
201	export function applyMigrations(db: Database): MigrationResult {
202	  const current = (db.prepare('PRAGMA user_version').get() as any).user_version as number;
203	  const target = MIGRATIONS.length;
204	
205	  if (current >= target) {
206	    return { from: current, to: target, applied: 0 };
207	  }
208	
209	  let applied = 0;
210	  for (let i = current; i < target; i++) {
211	    db.prepare('BEGIN IMMEDIATE').run();
212	    try {
213	      MIGRATIONS[i](db);
214	      db.prepare(`PRAGMA user_version = ${i + 1}`).run();
215	      db.prepare('COMMIT').run();
216	      applied++;
217	    } catch (e) {
218	      try { db.prepare('ROLLBACK').run(); } catch { /* already rolled back */ }
219	      throw new Error(`Migration ${i} → ${i + 1} failed: ${e}`);
220	    }
221	  }
222	
223	  return { from: current, to: target, applied };
224	}
225	
226	/**
227	 * Get the current migration version from the database.
228	 */
229	export function getMigrationVersion(db: Database): number {
230	  return (db.prepare('PRAGMA user_version').get() as any).user_version as number;
231	}

